import { Controller, Get, Post, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const STATUSES = ['진행', '완료', '취소'];
// 가정: 실사 완료 결과는 asset_change에 '실사' 변동으로 기록한다 (변동 상태는 결재 비연계 건이라 '기안')
const CHANGE_TYPE = '실사';
const CHANGE_STATUS = '기안';

const SELECT_COLUMNS =
  'asset_inspection_id AS "assetInspectionId", '
  + 'asset_inspection_plan_id AS "assetInspectionPlanId", '
  + 'fixed_asset_id AS "fixedAssetId", '
  + 'inspection_status AS "inspectionStatus", '
  + 'inspection_result AS "inspectionResult", '
  + 'inspected_at AS "inspectedAt" ';

function parseId(value: unknown, label: string): string {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^[0-9]+$/.test(value)) {
    return value;
  }
  throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
}

function parseCount(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const text = String(value);
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값이 올바르지 않습니다.');
  }
  return Number(text);
}

function optionalText(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '실사 결과는 글자로 입력해야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr02506Controller {
  @Post('/asset-inspections')
  @HttpCode(200)
  async createAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const planId = parseId(data['assetInspectionPlanId'], '실사계획');
    const assetId = parseId(data['fixedAssetId'], '고정자산');
    const result = optionalText(data['inspectionResult']);
    return transaction(async (db) => {
      const plans = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM asset_inspection_plan '
          + 'WHERE asset_inspection_plan_id = CAST(:planId AS bigint)',
        { planId },
      );
      if (plans.length === 0) {
        throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
      }
      if (plans[0]['approvalStatus'] !== '승인') {
        throw new ApiError(409, 'INSPECTION_PLAN_NOT_APPROVED', '승인되지 않은 실사계획입니다.');
      }
      const assets = await db.query(
        'SELECT fixed_asset_id FROM fixed_asset WHERE fixed_asset_id = CAST(:assetId AS bigint)',
        { assetId },
      );
      if (assets.length === 0) {
        throw new ApiError(404, 'FIXED_ASSET_NOT_FOUND', '고정자산을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT asset_inspection_id FROM asset_inspection '
          + 'WHERE asset_inspection_plan_id = CAST(:planId AS bigint) '
          + 'AND fixed_asset_id = CAST(:assetId AS bigint)',
        { planId, assetId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '이미 해당 실사계획으로 등록된 자산입니다.');
      }
      const rows = await db.query(
        'INSERT INTO asset_inspection (asset_inspection_plan_id, fixed_asset_id, inspection_status, '
          + 'inspection_result, created_at, updated_at) '
          + 'VALUES (CAST(:planId AS bigint), CAST(:assetId AS bigint), :status, :result, now(), now()) '
          + 'RETURNING asset_inspection_id AS "assetInspectionId", inspection_status AS "inspectionStatus"',
        { planId, assetId, status: '진행', result },
      );
      return rows[0];
    });
  }

  @Get('/asset-inspections')
  async listAssetInspections(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const query = checks.queryOf(req.query);
    const page = parseCount(query['page'], 0, 'page');
    const size = Math.min(parseCount(query['size'], DEFAULT_SIZE, 'size'), MAX_SIZE);
    const params: Record<string, unknown> = { limit: size, offset: page * size };
    const conditions: string[] = [];
    const planRaw = query['assetInspectionPlanId'];
    if (planRaw !== undefined && planRaw !== null && planRaw !== '') {
      params['planId'] = parseId(planRaw, '실사계획');
      conditions.push('asset_inspection_plan_id = CAST(:planId AS bigint)');
    }
    const statusRaw = query['inspectionStatus'];
    if (statusRaw !== undefined && statusRaw !== null && statusRaw !== '') {
      const status = String(statusRaw);
      if (!STATUSES.includes(status)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '실사 상태 값이 올바르지 않습니다.');
      }
      params['status'] = status;
      conditions.push('inspection_status = :status');
    }
    const where = conditions.length > 0 ? ' WHERE ' + conditions.join(' AND ') + ' ' : ' ';
    return transaction(async (db) => {
      const countRows = await db.query(
        'SELECT CAST(COUNT(*) AS integer) AS total FROM asset_inspection' + where,
        params,
      );
      const items = await db.query(
        'SELECT ' + SELECT_COLUMNS + 'FROM asset_inspection' + where
          + 'ORDER BY asset_inspection_id DESC LIMIT :limit OFFSET :offset',
        params,
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }

  @Post('/asset-inspections/:assetInspectionId/complete')
  @HttpCode(200)
  async completeAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const id = parseId(req.params['assetInspectionId'], '실사정보');
    const data = checks.inputOf(req.body);
    const inputResult = optionalText(data['inspectionResult']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT inspection_status AS "inspectionStatus", inspection_result AS "inspectionResult", '
          + 'fixed_asset_id AS "fixedAssetId" FROM asset_inspection '
          + 'WHERE asset_inspection_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'INSPECTION_NOT_FOUND', '실사정보를 찾을 수 없습니다.');
      }
      if (rows[0]['inspectionStatus'] !== '진행') {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '진행 중인 실사만 처리할 수 있습니다.');
      }
      const result = inputResult !== null ? inputResult : (rows[0]['inspectionResult'] as string | null);
      if (result === null || result === undefined || result === '') {
        throw new ApiError(400, 'VALIDATION_FAILED', '실사 결과를 입력해 주세요.');
      }
      await db.execute(
        'UPDATE asset_inspection SET inspection_status = :status, inspection_result = :result, '
          + 'inspected_at = now(), updated_at = now() WHERE asset_inspection_id = CAST(:id AS bigint)',
        { status: '완료', result, id },
      );
      await db.execute(
        'INSERT INTO asset_change (fixed_asset_id, change_type, change_date, change_content, '
          + 'change_status, created_at, updated_at) '
          + 'VALUES (CAST(:assetId AS bigint), :changeType, CAST(now() AS date), :content, :changeStatus, now(), now())',
        {
          assetId: String(rows[0]['fixedAssetId']),
          changeType: CHANGE_TYPE,
          content: result,
          changeStatus: CHANGE_STATUS,
        },
      );
      return { inspectionStatus: '완료' };
    });
  }

  @Post('/asset-inspections/:assetInspectionId/cancel')
  @HttpCode(200)
  async cancelAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const id = parseId(req.params['assetInspectionId'], '실사정보');
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT inspection_status AS "inspectionStatus" FROM asset_inspection '
          + 'WHERE asset_inspection_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'INSPECTION_NOT_FOUND', '실사정보를 찾을 수 없습니다.');
      }
      if (rows[0]['inspectionStatus'] !== '진행') {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '진행 중인 실사만 처리할 수 있습니다.');
      }
      await db.execute(
        'UPDATE asset_inspection SET inspection_status = :status, updated_at = now() '
          + 'WHERE asset_inspection_id = CAST(:id AS bigint)',
        { status: '취소', id },
      );
      return { inspectionStatus: '취소' };
    });
  }

  @Delete('/asset-inspections/:assetInspectionId')
  async deleteAssetInspection(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const id = parseId(req.params['assetInspectionId'], '실사정보');
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT inspection_status AS "inspectionStatus" FROM asset_inspection '
          + 'WHERE asset_inspection_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'INSPECTION_NOT_FOUND', '실사정보를 찾을 수 없습니다.');
      }
      if (rows[0]['inspectionStatus'] !== '진행') {
        throw new ApiError(409, 'INSPECTION_STATUS_CONFLICT', '진행 중인 실사만 삭제할 수 있습니다.');
      }
      await db.execute(
        'DELETE FROM asset_inspection WHERE asset_inspection_id = CAST(:id AS bigint)',
        { id },
      );
      return {};
    });
  }
}

