import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

type Panel =
  | { kind: 'create' }
  | { kind: 'complete'; row: Row }
  | { kind: 'cancel'; row: Row }
  | { kind: 'delete'; row: Row }
  | null;

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['진행', '진행'],
  ['완료', '완료'],
  ['취소', '취소'],
];

export default function FnSfr02506Page({ role, notify }: PageProps) {
  const [planFilter, setPlanFilter] = useState<number | string>('');
  const [statusFilter, setStatusFilter] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [panel, setPanel] = useState<Panel>(null);

  const [planId, setPlanId] = useState<number | string>('');
  const [assetId, setAssetId] = useState<number | string>('');
  const [result, setResult] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/asset-inspections', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const running = useData<Page>(
    () => call<Page>('GET', '/asset-inspections', role, undefined, { inspectionStatus: '진행', page: 0, size: 1 }),
    [role],
  );

  const search = () => {
    setPage(0);
    setApplied({ assetInspectionPlanId: planFilter, inspectionStatus: statusFilter });
  };
  const reset = () => {
    setPlanFilter('');
    setStatusFilter('');
    setPage(0);
    setApplied({});
  };
  const refresh = () => {
    list.reload();
    running.reload();
  };
  const close = () => {
    setPanel(null);
    setResult('');
    setPlanId('');
    setAssetId('');
  };

  const openComplete = (row: Row) => {
    setResult(typeof row['inspectionResult'] === 'string' ? row['inspectionResult'] : '');
    setPanel({ kind: 'complete', row });
  };

  const submitCreate = async () => {
    if (planId === '' || assetId === '') {
      throw new Error('실사계획과 고정자산을 선택해 주세요.');
    }
    await call('POST', '/asset-inspections', role, {
      assetInspectionPlanId: planId,
      fixedAssetId: assetId,
      inspectionResult: result,
    });
    notify('실사를 시작했습니다.');
    close();
    refresh();
  };

  const submitComplete = async (row: Row) => {
    if (result.trim() === '') {
      throw new Error('실사 결과를 입력해 주세요.');
    }
    await call('POST', `/asset-inspections/${row['assetInspectionId']}/complete`, role, {
      inspectionResult: result,
    });
    notify('실사를 완료했습니다.');
    close();
    refresh();
  };

  const submitCancel = async (row: Row) => {
    await call('POST', `/asset-inspections/${row['assetInspectionId']}/cancel`, role, {});
    notify('실사를 취소했습니다.');
    close();
    refresh();
  };

  const submitDelete = async (row: Row) => {
    await call('DELETE', `/asset-inspections/${row['assetInspectionId']}`, role);
    notify('실사를 삭제했습니다.');
    close();
    refresh();
  };

  const columns: Column[] = [
    { key: 'assetInspectionId', label: '실사정보 ID' },
    {
      key: 'assetInspectionPlanId',
      label: '실사계획',
      render: (r) => <RefName table="asset_inspection_plan" role={role} value={r['assetInspectionPlanId']} />,
    },
    {
      key: 'fixedAssetId',
      label: '고정자산',
      render: (r) => <RefName table="fixed_asset" role={role} value={r['fixedAssetId']} />,
    },
    { key: 'inspectionStatus', label: '실사 상태', render: (r) => <Badge value={r['inspectionStatus']} /> },
    { key: 'inspectionResult', label: '실사 결과' },
    { key: 'inspectedAt', label: '실사 완료 일시', render: (r) => <DateText value={r['inspectedAt']} time /> },
    {
      key: 'actions',
      label: '처리',
      render: (r) =>
        r['inspectionStatus'] === '진행' ? (
          <span>
            <button type="button" onClick={(e) => { e.stopPropagation(); openComplete(r); }}>완료</button>
            <button type="button" onClick={(e) => { e.stopPropagation(); setPanel({ kind: 'cancel', row: r }); }}>취소</button>
            <button type="button" onClick={(e) => { e.stopPropagation(); setPanel({ kind: 'delete', row: r }); }}>삭제</button>
          </span>
        ) : null,
    },
  ];

  const data = list.data;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>진행 중 실사</h2>
        <Tiles items={[['진행 중 건수', running.data ? running.data.total : 0]]} />
      </section>
      <section className="box span-8">
        <h2>실사 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="실사계획">
            <LookupSelect table="asset_inspection_plan" role={role} value={planFilter} onChange={setPlanFilter} />
          </Field>
          <Field label="실사 상태">
            <Select value={statusFilter} onChange={setStatusFilter} options={STATUS_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => setPanel({ kind: 'create' })}>실사 시작</button>
        </Band>
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={data ? data.items : []} empty="실사 내역이 없습니다." />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>

      {panel && panel.kind === 'create' ? (
        <Drawer title="실사 시작" onClose={close}>
          <Form onSubmit={submitCreate} submit="시작">
            <Field label="실사계획" required>
              <LookupSelect table="asset_inspection_plan" role={role} value={planId} onChange={setPlanId} />
            </Field>
            <Field label="고정자산" required>
              <LookupSelect table="fixed_asset" role={role} value={assetId} onChange={setAssetId} />
            </Field>
            <Field label="실사 결과" wide>
              <TextInput value={result} onChange={setResult} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {panel && panel.kind === 'complete' ? (
        <Drawer title="실사 완료" onClose={close}>
          <Pairs
            items={[
              ['실사정보 ID', String(panel.row['assetInspectionId'])],
              ['고정자산', <RefName table="fixed_asset" role={role} value={panel.row['fixedAssetId']} />],
            ]}
          />
          <Form onSubmit={() => submitComplete(panel.row)} submit="완료 처리">
            <Field label="실사 결과" required wide>
              <TextInput value={result} onChange={setResult} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {panel && panel.kind === 'cancel' ? (
        <Drawer title="실사 취소" onClose={close}>
          <Form onSubmit={() => submitCancel(panel.row)} submit="취소 처리" danger note="진행 중인 실사를 취소합니다." />
        </Drawer>
      ) : null}

      {panel && panel.kind === 'delete' ? (
        <Drawer title="실사 삭제" onClose={close}>
          <Form onSubmit={() => submitDelete(panel.row)} submit="삭제" danger note="진행 중인 실사를 삭제합니다." />
        </Drawer>
      ) : null}
    </div>
  );
}
